#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] [x..n-1-y] [n-y..n-1] -> [n-y..n-1] [x..n-1-y] [0..x-1]
    vector<int> np;
    for (int i = n-y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n-y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    // Place elements 1,2,...,n into positions 0,1,...,n-1
    // After placing k elements, positions 0..k-1 are fixed.
    // We work on the subarray p[k..n-1] conceptually, but operations are on full array.

    for(int k=0; k<n-2; k++){
        int pos=-1;
        for(int i=k;i<n;i++) if(p[i]==k+1){pos=i;break;}
        if(pos==k) continue;

        int remaining = n - k; // elements from k to n-1
        if(remaining < 3) break; // can't do operation with less than 3 elements in play

        // We need element at pos to go to position k.
        // Operation on full array: x = prefix len, y = suffix len, x+y < n
        // Move element from pos to position k using the block swap.

        // Strategy: first move element to position n-1 (last), then move it to position k.

        // Step 1: bring element to last position
        if(pos != n-1) {
            // x = pos+1, y = n-1-pos, but x+y = n, need x+y < n
            // So use x = pos+1, y = n-1-pos-1 = n-pos-2 (if > 0, i.e., pos < n-2)
            // After op: [suffix y] [middle] [prefix x] - element was at end of prefix, goes to end
            // Actually: element at pos (index pos in prefix of length pos+1) -> goes to position n - (pos+1) + pos = n-1. Yes!
            // But we need middle non-empty: n - x - y >= 1, i.e., n - (pos+1) - (n-pos-2) = 1. OK.
            if(pos < n-2) {
                int x = pos+1, y = n-pos-2;
                if(y == 0) { /* skip */ }
                else { ops.push_back({x,y}); apply(p,x,y); }
            }
            for(int i=k;i<n;i++) if(p[i]==k+1){pos=i;break;}
        }
        if(pos==k) continue;
        // Step 2: element should be near end. Bring to position k.
        // x=k+1, y=n-pos. Need x+y<n => k+1+n-pos<n => k+1<pos. 
        if(k+1 < pos && pos < n) {
            int x=k+1, y=n-pos;
            ops.push_back({x,y}); apply(p,x,y);
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
